    a: "조건 분기의 결과가 정렬된 데이터에서는 한동안 한쪽으로 쭉 이어지다 한 번 바뀌므로 분기 예측기가 거의 다 맞힌다. 무작위 데이터에서는 패턴이 없어 절반 가까이 틀리고, 틀릴 때마다 파이프라인을 비우는 비용을 낸다. 연산량은 같아도 예측 실패 횟수가 실행 시간을 가른다.",
