    a: "너무 길면 앞 작업이 오래 잡고 있어 FCFS와 비슷해지고 응답성이 떨어진다. 너무 짧으면 응답은 고르지만 컨텍스트 스위칭이 잦아져 전환 비용과 캐시를 다시 채우는 비용 때문에 실제 일하는 시간이 줄어든다. 대부분의 대화형 작업이 한 조각 안에 끝날 정도로 잡는다.",
