    a: "히트하면 메모리를 한 번(100ns), 미스하면 테이블 한 번과 데이터 한 번(200ns) 읽는다. 0.9 × 100 + 0.1 × 200 = 110ns다. 테이블이 4단계면 미스 비용이 500ns가 되어 0.9 × 100 + 0.1 × 500 = 140ns로 늘어난다.",
