    a: "아니다. 헤더 가드는 한 소스 파일(번역 단위) 안에서 같은 헤더가 두 번 펼쳐지는 것만 막는다. 다른 소스 파일은 각자 그 헤더를 다시 펼치므로, 소스가 100개면 100번 처리되는 것은 그대로다.",
