    a: "돌아갈 주소가 지역 배열과 같은 스택에 붙어 있어서, 배열 경계를 넘겨 쓰면 돌아갈 주소까지 덮이고 함수가 끝날 때 공격자가 적은 주소로 제어가 넘어간다. 스택 카나리(덮였는지 검사), 실행 불가능 스택(NX), ASLR(주소 무작위화), 최신 CPU의 섀도 스택으로 막는다. C# 관리 코드는 배열 경계를 검사하므로 unsafe·네이티브 코드에서만 해당한다.",
