    a: "f = g + h로 다음 노드를 고른다. g는 출발점부터의 실제 비용, h는 목표까지의 추정 비용이다. h = 0이면 다익스트라와 같고, h가 있으면 목표 쪽부터 살펴 탐색 범위가 줄어든다. h가 실제 거리를 넘지 않으면(허용 가능) 최단 경로를 보장하고, 닫힌 목록을 쓰는 구현에서는 일관성(한 칸 이동할 때 h가 간선 비용보다 더 줄지 않음)까지 있어야 노드를 다시 열 필요가 없다. h가 과대평가하면 빨라질 수 있지만 최단이 아닐 수 있다.",
